-- Статьи с большой глубиной просмотра заканчивались продажей подписки родителю,
-- хотя читает их преподаватель и владелец школы. Переписываем концовки под
-- запрос и боль этого читателя и даём конкретный следующий шаг.

-- 1. Экономика репетиторства. Текст о том, что почасовая модель упирается
-- в потолок, но выход предлагался только ученику. Добавляем разбор для того,
-- кто этот час продаёт.
UPDATE t_p78828167_tutor_platform_1.feed_articles
SET content = content || E'\n\n## А если вы по другую сторону стола\n\nВсё сказанное выше читается по-разному в зависимости от того, кто вы.\n\nРодитель видит здесь способ сэкономить. Репетитор — приговор собственной профессии: доход упёрся в количество часов в сутках, а цену держит дефицит, который технологии размывают.\n\nВывод из этого не «бросайте преподавать». Вывод в том, что менять час на деньги — не единственная модель.\n\n**Курс в записи продаётся параллельно занятиям.** Вы записываете программу один раз, а получаете за неё столько раз, сколько её купили. Ваше расписание перестаёт быть потолком дохода.\n\n**Объяснять одно и то же в двадцатый раз больше не нужно.** Типовые вопросы между занятиями забирает ИИ-наставник, обученный строго на вашей программе. Ваше время остаётся на то, ради чего к вам и идут: разбор сложного и живое участие.\n\n**Упаковка перестаёт быть стеной.** Методичка на курс из 12 уроков пишется неделями вечеров — и всё это время вы не зарабатываете, а готовитесь. ИИ собирает структуру за минуту: модули, уроки с конспектами, задания, квизы, рекомендованную цену и тексты объявления. Дальше вы правите готовое, а не смотрите в пустой документ.\n\nЧестная оговорка: курс сам себя не продаст. Первых учеников всё равно искать вам — поэтому конструктор отдаёт вместе с программой и каналы, где их искать.\n\nПопробовать можно без карты и регистрации: [соберите программу своего курса](/school-builder) и посмотрите, что получится. PDF останется у вас в любом случае. Условия и комиссия — [на странице для репетиторов](/repetitoram).',
    summary = 'Родители платят под 100 тысяч за год по одному предмету и не понимают, за что. Разбираем экономику репетиторства по косточкам: сколько стоит время, сколько — дефицит, и что делать преподавателю, чей доход упёрся в часы в сутках.',
    updated_at = now()
WHERE slug = 'ekonomika-repetitorstva-pochemu-chas-stoit-1500';

-- 2. Доходимость. Статья прямо про боль владельца школы, а вела на мини-курсы
-- для школьников — то есть на чужой продукт.
UPDATE t_p78828167_tutor_platform_1.feed_articles
SET content = regexp_replace(
      content,
      '\[Посмотреть, как это работает\]\(/mini-course\) — бесплатные мини-курсы на один вечер\.',
      E'## Если считать это своей задачей\n\nДоходимость — не свойство учеников, а свойство конструкции курса. Её можно закладывать на этапе программы, а не чинить постфактум рассылками.\n\nКонструктор УЧИСЬПРО собирает программу именно так: модули идут от простого к сложному, у каждого урока есть практическое задание и проверочный квиз, а не только видео. Первую победу можно поставить на первую неделю, переставив модули — это видно прямо в структуре.\n\nДальше ученику круглосуточно отвечает ИИ-наставник, обученный на вашей программе и не уводящий в общие рассуждения из интернета. Тот самый вопрос в девять вечера получает ответ в девять вечера, а не через три дня.\n\nБез абонплаты: платформа берёт 8% с продажи. Нет продаж — вы ничего не должны.\n\n[Соберите программу курса бесплатно](/school-builder) — без карты и регистрации, PDF останется у вас. Условия для школ и репетиторов — [здесь](/repetitoram).',
      'g'
    ),
    summary = 'Не на первой неделе, когда сложно, и не на последней, когда устал. Именно на третьей. Разбираем механику отвала, почему школы её не видят и что поднимает доходимость без единого лишнего рубля в рекламу.',
    updated_at = now()
WHERE slug = 'pochemu-ucheniki-brosayut-kursy-na-tretey-nedele';
